entries[90531] = { ["name"] = "Pläne: Geistereisenschildstachel", ["text"] = "Benötigt Schmiedekunst (540)\nBenötigt Die Klaxxi\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines Geistereisenschildstachel.\n\nGeistereisenschildstachel\nWird beim Anlegen gebunden\nBenötigt Stufe 85\nBenutzen: Bringt einen Geistereisenstachel an Eurem Schild an, der beim Blocken manchmal 280 Schaden verursacht.\n\nDurch das Anbringen des Geistereisenstachel wird der Gegenstand seelengebunden.\nVerkaufspreis:\nBenötigt Geistereisenbarren (12)" }
entries[90532] = { ["name"] = "Pläne: Waffenkette aus lebendigem Stahl", ["text"] = "Benötigt Schmiedekunst (540)\nBenötigt Die Klaxxi\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung einer Waffenkette aus lebendigem Stahl.\n\nWaffenkette aus lebendigem Stahl\nWird beim Anlegen gebunden\nBenötigt Stufe 85\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert und Eure Waffenkunde um 200 erhöht. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen der Waffenkette wird der Gegenstand seelengebunden.\nBenötigt Lebendiger Stahl" }
